264 | 
265 |         long millis = endMillis - startMillis;
266 |         if (millis < 28 * DateUtils.MILLIS_PER_DAY) {
267 |             return formatDuration(millis, format, padWithZeros);
268 |         }
269 | 
270 |         Token[] tokens = lexx(format);
271 | 
272 |         // timezones get funky around 0, so normalizing everything to GMT 
273 |         // stops the hours being off
274 |         Calendar start = Calendar.getInstance(timezone);
275 |         start.setTime(new Date(startMillis));
276 |         Calendar end = Calendar.getInstance(timezone);
277 |         end.setTime(new Date(endMillis));
278 | 
279 |         // initial estimates
280 |         int milliseconds = end.get(Calendar.MILLISECOND) - start.get(Calendar.MILLISECOND);
281 |         int seconds = end.get(Calendar.SECOND) - start.get(Calendar.SECOND);
282 |         int minutes = end.get(Calendar.MINUTE) - start.get(Calendar.MINUTE);
283 |         int hours = end.get(Calendar.HOUR_OF_DAY) - start.get(Calendar.HOUR_OF_DAY);
284 |         int days = end.get(Calendar.DAY_OF_MONTH) - start.get(Calendar.DAY_OF_MONTH);
285 |         int months = end.get(Calendar.MONTH) - start.get(Calendar.MONTH);
286 |         int years = end.get(Calendar.YEAR) - start.get(Calendar.YEAR);
287 | 
288 |         // each initial estimate is adjusted in case it is under 0
289 |         while (milliseconds < 0) {
290 |             milliseconds += 1000;
291 |             seconds -= 1;
292 |         }
293 |         while (seconds < 0) {
294 |             seconds += 60;
295 |             minutes -= 1;
296 |         }
297 |         while (minutes < 0) {
298 |             minutes += 60;
299 |             hours -= 1;
300 |         }
301 |         while (hours < 0) {
302 |             hours += 24;
303 |             days -= 1;
304 |         }
305 |         while (days < 0) {
306 |             days += 31;
307 | //days += 31; // TODO: Need tests to show this is bad and the new code is good.
308 | // HEN: It's a tricky subject. Jan 15th to March 10th. If I count days-first it is 
309 | // 1 month and 26 days, but if I count month-first then it is 1 month and 23 days.
310 | // Also it's contextual - if asked for no M in the format then I should probably 
311 | // be doing no calculating here.
312 |             months -= 1;
313 |         }
