322 |         days -= reduceAndCorrect(start, end, Calendar.DAY_OF_MONTH, days);
323 |         months -= reduceAndCorrect(start, end, Calendar.MONTH, months);
324 |         years -= reduceAndCorrect(start, end, Calendar.YEAR, years);
