 90 |     private Integer getPivotRow(SimplexTableau tableau, final int col) {
 91 |         // create a list of all the rows that tie for the lowest score in the minimum ratio test
 92 |         List<Integer> minRatioPositions = new ArrayList<Integer>();
 93 |         double minRatio = Double.MAX_VALUE;
 94 |         for (int i = tableau.getNumObjectiveFunctions(); i < tableau.getHeight(); i++) {
 95 |             final double rhs = tableau.getEntry(i, tableau.getWidth() - 1);
 96 |             final double entry = tableau.getEntry(i, col);
 97 | 
 98 |             if (Precision.compareTo(entry, 0d, maxUlps) > 0) {
 99 |                 final double ratio = rhs / entry;
100 |                 // check if the entry is strictly equal to the current min ratio
101 |                 // do not use a ulp/epsilon check
102 |                 final int cmp = Double.compare(ratio, minRatio);
103 |                 if (cmp == 0) {
104 |                     minRatioPositions.add(i);
105 |                 } else if (cmp < 0) {
106 |                     minRatio = ratio;
107 |                     minRatioPositions = new ArrayList<Integer>();
108 |                     minRatioPositions.add(i);
109 |                 }
110 |             }
111 |         }
112 | 
113 |         if (minRatioPositions.size() == 0) {
114 |             return null;
115 |         } else if (minRatioPositions.size() > 1) {
116 |             // there's a degeneracy as indicated by a tie in the minimum ratio test
117 | 
118 |             // 1. check if there's an artificial variable that can be forced out of the basis
119 |                 for (Integer row : minRatioPositions) {
120 |                     for (int i = 0; i < tableau.getNumArtificialVariables(); i++) {
121 |                         int column = i + tableau.getArtificialVariableOffset();
122 |                         final double entry = tableau.getEntry(row, column);
123 |                         if (Precision.equals(entry, 1d, maxUlps) && row.equals(tableau.getBasicRow(column))) {
124 |                             return row;
125 |                         }
126 |                     }
127 |                 }
128 | 
129 |             // 2. apply Bland's rule to prevent cycling:
130 |             //    take the row for which the corresponding basic variable has the smallest index
131 |             //
132 |             // see http://www.stanford.edu/class/msande310/blandrule.pdf
133 |             // see http://en.wikipedia.org/wiki/Bland%27s_rule (not equivalent to the above paper)
134 |             //
135 |             // Additional heuristic: if we did not get a solution after half of maxIterations
136 |             //                       revert to the simple case of just returning the top-most row
137 |             // This heuristic is based on empirical data gathered while investigating MATH-828.
138 |                 Integer minRow = null;
139 |                 int minIndex = tableau.getWidth();
140 |                 for (Integer row : minRatioPositions) {
141 |                     int i = tableau.getNumObjectiveFunctions();
142 |                     for (; i < tableau.getWidth() - 1 && minRow != row; i++) {
143 |                         if (row == tableau.getBasicRow(i)) {
144 |                             if (i < minIndex) {
145 |                                 minIndex = i;
146 |                                 minRow = row;
147 |                             }
148 |                         }
149 |                     }
150 |                 }
151 |                 return minRow;
152 |         }
153 |         return minRatioPositions.get(0);
154 |     }

